<script setup>
import {t} from '../i18n.js';
defineProps({assessment:{type:Object,required:true},inventory:Object});
defineEmits(['ask']);
function width(group,planned=false){const earned=Math.min(group.required,group.completed||0);return (planned?Math.min(group.inProgress||0,Math.max(0,group.required-earned)):earned)/group.required*100+'%';}
function officialUrl(value){try{const u=new URL(value);return u.protocol==='https:'&&(u.hostname==='psu.edu'||u.hostname.endsWith('.psu.edu'))?u.href:null;}catch{return null;}}
</script>
<template>
 <section class="minor-planner" aria-labelledby="minor-title">
  <div class="minor-heading"><div><h2 id="minor-title">{{t('Math minor planner')}}</h2><p>University Park · {{assessment.catalogYear}} · {{t('Reference estimate')}}</p></div><button class="outline-button" @click="$emit('ask')">{{t('Ask about my Math minor')}}</button></div>
  <p v-if="!assessment.inventoryAvailable" class="minor-warning">{{t('Re-upload a PDF with course tables to compare this minor. Missing courses are not treated as zero.')}}</p>
  <template v-else>
   <div class="minor-metrics"><span><strong>{{assessment.completed}}</strong>{{t('Completed')}}</span><span><strong>{{assessment.planned}}</strong>{{t('In progress / planned')}}</span><span><strong>{{assessment.additionalCredits}}</strong>{{t('Minimum additional credits')}}</span></div>
   <p v-if="!assessment.catalogYearMatches || !assessment.campusMatches" class="minor-warning">{{t('This is a 2026–27 University Park comparison. Your report follows a different or unconfirmed campus/year:')}} {{assessment.reportCatalogYear||t('Unknown totals')}}.</p>
   <p class="minor-note">{{t('Based only on courses found in this PDF. Six credits unique from major prescribed courses, substitutions and minor declaration still need adviser confirmation.')}}</p>
   <p v-if="assessment.unparsedRowCount" class="minor-warning">{{assessment.unparsedRowCount}} {{t('course rows could not be fully read.')}}</p>
   <article v-for="group in assessment.groups" :key="group.id" class="minor-group">
    <div class="minor-group-heading"><h3>{{t(group.label)}}</h3><strong>{{group.status==='completed'?t('Complete'):group.status==='covered_by_plan'?t('Covered by planned courses'):group.remaining+' '+t('additional credits')}}</strong></div>
    <div class="minor-track" role="img" :aria-label="`${group.label}: ${group.completed} earned, ${group.inProgress} planned, ${group.required} required`"><span :style="{width:width(group)}"></span><span class="planned" :style="{width:width(group,true)}"></span></div>
    <p>{{group.completed}} {{t('Completed')}} · {{group.inProgress}} {{t('In progress / planned')}} / {{group.required}} {{t('credits minimum')}}</p>
    <ul v-if="group.matchedCourses.length" class="minor-matches"><li v-for="course in group.matchedCourses" :key="course.code"><strong>{{course.code}}</strong> · {{course.countedCredits}} {{t('credits')}} · {{course.term}} · {{course.grade==='IP'?t('In progress / planned'):course.grade}}</li></ul>
    <details v-if="group.options.length"><summary>{{t('Possible courses to fill this gap')}} · {{group.options.length}}</summary><p>{{t('Options require prerequisite and duplicate-credit checks; availability is not verified.')}}</p><ul><li v-for="course in group.options" :key="course.code"><a v-if="officialUrl(course.sourceUrl)" :href="officialUrl(course.sourceUrl)" target="_blank" rel="noopener noreferrer">{{course.code}} — {{course.title}}</a><span v-else>{{course.code}} — {{course.title}}</span><p>{{course.creditsMin}}<template v-if="course.creditsMax!==course.creditsMin">–{{course.creditsMax}}</template> {{t('credits')}} · {{t('Prerequisites:')}} {{course.prerequisiteText||t('Needs confirmation')}}</p></li></ul></details>
   </article>
   <details v-if="assessment.excludedCourses?.length"><summary>{{t('Courses not automatically counted')}} · {{assessment.excludedCourses.length}}</summary><ul><li v-for="(course,i) in assessment.excludedCourses" :key="i">{{course.code}} · {{course.grade}} — {{t(course.reason)}}</li></ul></details>
  </template>
  <details v-if="inventory?.courses?.length"><summary>{{t('Extracted course history')}} · {{inventory.courses.length}}</summary><p>{{t('Repeated appearances across requirement sections are counted once.')}}</p><ul><li v-for="course in inventory.courses" :key="course.code+course.term">{{course.code}} · {{course.term}} · {{course.credits}} {{t('credits')}} · {{course.grade}}<span v-if="course.requiresReview"> · {{t('Needs review')}}</span></li></ul></details>
  <details><summary>{{t('Rules and checks')}}</summary><p>{{t('All counted courses require C or better. Planned courses count only if passed with the required grade.')}}</p><ul><li v-for="note in assessment.reviewNotes" :key="note">{{t(note)}}</li></ul></details>
  <div class="minor-links"><a :href="officialUrl(assessment.sourceUrl)" target="_blank" rel="noopener noreferrer">{{t('Official Bulletin ↗')}}</a><a :href="officialUrl(assessment.departmentUrl)" target="_blank" rel="noopener noreferrer">{{t('Math department guidance ↗')}}</a></div>
 </section>
</template>
<style scoped>
.minor-planner{margin:28px 0;padding:26px;border:1px solid var(--line);border-radius:14px;background:var(--surface);font-size:var(--text-body);line-height:1.7}.minor-heading,.minor-group-heading{display:flex;justify-content:space-between;gap:16px;align-items:center}.minor-heading h2{font-size:var(--text-heading);font-weight:600}.minor-heading p,.minor-note,.minor-group p{color:var(--muted);font-size:var(--text-small)}.minor-metrics{display:flex;flex-wrap:wrap;gap:32px;margin:20px 0}.minor-metrics span{display:flex;flex-direction:column;color:var(--muted);font-size:var(--text-small)}.minor-metrics strong{font-size:28px;color:var(--ink);font-weight:600}.minor-warning{padding:12px;background:var(--surface-subtle);border-left:3px solid var(--psu-pugh);margin:12px 0;font-size:var(--text-small)}.minor-group{padding:18px 0;border-bottom:1px solid var(--line)}.minor-group h3{font-size:var(--text-body);font-weight:600;margin:0}.minor-group-heading>strong{font-size:var(--text-small);color:var(--psu-blue)}.minor-track{height:9px;border-radius:5px;overflow:hidden;background:var(--line);display:flex;margin:12px 0 6px}.minor-track>span{background:var(--psu-blue)}.minor-track>.planned{background:var(--psu-pugh)}.minor-planner ul{padding-left:20px;font-size:var(--text-small)}.minor-planner li{margin:6px 0}.minor-planner details{margin-top:14px;font-size:var(--text-small)}.minor-planner summary{cursor:pointer;font-weight:500}.minor-links{display:flex;gap:20px;flex-wrap:wrap;margin-top:18px}.minor-planner a{color:var(--psu-blue);text-underline-offset:3px}@media(max-width:600px){.minor-planner{padding:18px}.minor-heading{align-items:flex-start;flex-direction:column}.minor-group-heading{align-items:flex-start}.minor-metrics{gap:20px}}
</style>
